from itertools import combinations_with_replacement
from collections import Counter

def is_anagram(n1, n2):
    return Counter(str(n1)) == Counter(str(n2))

found_sets = []
for nums in combinations_with_replacement(range(1, 1000), 4):
    if len(set(nums)) != 4:
        continue
    valid_set = True
    for i in range(4):
        if not is_anagram(nums[i], sum(nums[:i] + nums[i+1:])):
            valid_set = False
            break
    if valid_set:
        found_sets.append(tuple(sorted(nums)))
        if len(found_sets) == 5:
            break

print(f"\\boxed{tuple(found_sets)}")
```

